func fanOut(msg Message, recipients []chan Message) {
	var wg sync.WaitGroup
	for _, ch := range recipients {            // recipients computed at runtime
		wg.Add(1)
		go func(ch chan Message) {
			defer wg.Done()
			ch <- msg.Clone()                  // own copy per recipient
		}(ch)
	}
	wg.Wait()                                  // fan-out complete
}
